async function toggleVoiceRecording(){if(voiceRecorder&&voiceRecorder.state==="recording"){voiceRecorder.stop();return;}if(!activeChat)return;if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==="undefined"){toast("Запись голоса не поддерживается этим приложением.");return;}try{voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});const types=["audio/webm;codecs=opus","audio/webm","audio/mp4","audio/ogg"];const mime=types.find(t=>MediaRecorder.isTypeSupported(t));voiceRecorder=new MediaRecorder(voiceStream,mime?{mimeType:mime}:undefined);voiceChunks=[];voiceCancelled=false;voiceStartedAt=Date.now();voiceRecorder.ondataavailable=e=>{if(e.data&&e.data.size)voiceChunks.push(e.data);};voiceRecorder.onstop=finishVoiceRecording;voiceRecorder.start(250);$("m-voice-record").classList.add("m-recording");$("m-voice-record").textContent="■";$("m-voice-record").title="Остановить и отправить";$("m-voice-record").setAttribute("aria-label","Остановить и отправить запись");$("m-voice-status").classList.remove("hidden");$("m-voice-status").textContent="● Запись 00:00";$("m-voice-cancel").classList.remove("hidden");voiceClock=setInterval(()=>{const s=Math.floor((Date.now()-voiceStartedAt)/1000),el=$("m-voice-status");if(el)el.textContent="● Запись "+Math.floor(s/60)+":"+String(s%60).padStart(2,"0");if(s>=300&&voiceRecorder&&voiceRecorder.state==="recording"){toast("Достигнут лимит записи 5 минут.");voiceRecorder.stop();}},250);}catch(e){toast("Не удалось включить микрофон: "+(e.message||"проверь разрешение"));resetVoiceUI();}}
function resetVoiceUI(){clearInterval(voiceClock);voiceClock=null;if(voiceStream)voiceStream.getTracks().forEach(t=>t.stop());voiceStream=null;voiceRecorder=null;voiceChunks=[];const b=$("m-voice-record"),s=$("m-voice-status"),x=$("m-voice-cancel");if(b){b.classList.remove("m-recording");b.textContent="🎙";b.title="Голосовое сообщение";b.setAttribute("aria-label","Записать голосовое сообщение");}if(s)s.classList.add("hidden");if(x)x.classList.add("hidden");}
function cancelVoiceRecording(){voiceCancelled=true;if(voiceRecorder&&voiceRecorder.state!=="inactive")voiceRecorder.stop();else{resetVoiceUI();voiceCancelled=false;}}
async function finishVoiceRecording(){const recorder=voiceRecorder,blob=new Blob(voiceChunks,{type:recorder?.mimeType||"audio/webm"}),duration=Math.max(1,Math.round((Date.now()-voiceStartedAt)/1000)),recipient=activeChat,cancelled=voiceCancelled;resetVoiceUI();voiceCancelled=false;if(cancelled)return;if(!recipient||!current?.user||!blob.size)return;if(duration>300){toast("Голосовое сообщение ограничено 5 минутами.");return;}if(blob.size>15*1024*1024){toast("Запись слишком большая (максимум 15 МБ).");return;}const ext=blob.type.includes("mp4")?"mp4":blob.type.includes("ogg")?"ogg":blob.type.includes("mpeg")?"mp3":"webm";const path=current.user.id+"/"+recipient.id+"/"+Date.now()+"-"+Math.random().toString(36).slice(2)+"."+ext;const button=$("m-voice-record");if(button)button.disabled=true;toast("Отправляю голосовое сообщение…");try{const upload=await current.supabase.storage.from("voice-messages").upload(path,blob,{contentType:blob.type||"audio/webm",upsert:false});if(upload.error)throw upload.error;const marker="[[feather-voice|"+path+"|"+duration+"]]";const sent=await current.supabase.from("messages").insert({sender_id:current.user.id,receiver_id:recipient.id,text:marker});if(sent.error){await current.supabase.storage.from("voice-messages").remove([path]);throw sent.error;}await loadMessages(recipient);await loadChats();toast("Голосовое сообщение отправлено.");}catch(e){toast("Не удалось отправить голосовое: "+(e.message||"ошибка"));}finally{if(button)button.disabled=false;}}
async function sendMessage(e){e.preventDefault();const field=$("m-compose"),text=field.value.trim();if(!text||(!activeChat&&!activeSpace))return;sendTypingState(false);const button=e.submitter||document.querySelector("#m-composer button[type=submit]");button.disabled=true;try{if(activeSpace){const r=await current.supabase.from("community_messages").insert({space_id:activeSpace.id,sender_id:current.user.id,text});if(r.error)throw r.error;field.value="";await loadSpaceMessages(activeSpace);await loadSpaces();}else{const r=await current.supabase.from("messages").insert({sender_id:current.user.id,receiver_id:activeChat.id,text});if(r.error)throw r.error;field.value="";await loadMessages(activeChat);await loadChats();}}catch(err){toast("Не удалось отправить: "+(err.message||"ошибка"),"error");}finally{button.disabled=false;field.focus();}}
